CREATE TABLE CUSTOMERS (
    ID INT,
    NAME VARCHAR(255),
    PRIMARY KEY (ID)
);

CREATE TABLE ORDERS (
    ID INT,
    CUSTOMERID INT,
    PRIMARY KEY (ID),
    FOREIGN KEY (CUSTOMERID) REFERENCES CUSTOMERS(ID)
);

