schema:
CREATE TABLE PRODUCT (
    PRODUCT_KEY INT,
    PRIMARY KEY (PRODUCT_KEY)
);
CREATE TABLE CUSTOMER (
    CUSTOMER_ID INT,
    PRODUCT_KEY INT,
    PRIMARY KEY (CUSTOMER_ID),
    FOREIGN KEY (PRODUCT_KEY) REFERENCES PRODUCT(PRODUCT_KEY)
);

counterexample:
-- No counterexample can be generated as the queries are logically equivalent under the given schema.
-- Any valid data will produce identical results for Q1 and Q2.

INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (101);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (102);

INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 101);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (2, 102);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (3, 101);

-- Q1 Result (empty set, because 1 != 2):
-- SELECT CUSTOMER_ID FROM CUSTOMER GROUP BY 1 HAVING COUNT(DISTINCT PRODUCT_KEY) = (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT);
-- (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT) evaluates to 2.
-- For each customer, COUNT(DISTINCT PRODUCT_KEY) evaluates to 1.
-- 1 = 2 is FALSE for all groups.

-- Q2 Result (empty set, because 1 != 2):
-- WITH CTE AS ( SELECT CUSTOMER_ID, COUNT(DISTINCT PRODUCT_KEY) AS CT FROM CUSTOMER GROUP BY CUSTOMER_ID)
-- SELECT CUSTOMER_ID FROM CTE WHERE CT = (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT);
-- CTE will have (1,1), (2,1), (3,1).
-- (SELECT COUNT(DISTINCT PRODUCT_KEY) FROM PRODUCT) evaluates to 2.
-- WHERE CT = 2 is FALSE for all rows in CTE.

