CREATE TABLE EMPLOYEE (
    EMPLOYEE_ID INT,
    NAME VARCHAR(255),
    EXPERIENCE_YEARS INT,
    PRIMARY KEY (EMPLOYEE_ID),
    CHECK (EXPERIENCE_YEARS >= 0)
);
CREATE TABLE PROJECT (
    PROJECT_ID INT,
    EMPLOYEE_ID INT,
    PRIMARY KEY (PROJECT_ID, EMPLOYEE_ID),
    FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE(EMPLOYEE_ID)
);

counterexample:
-- No counterexample can be generated that satisfies the problem's constraints.
-- The foreign key constraint `FOREIGN KEY (EMPLOYEE_ID) REFERENCES EMPLOYEE(EMPLOYEE_ID)`
-- ensures that every EMPLOYEE_ID in the PROJECT table always has a match in the EMPLOYEE table.
-- This makes the INNER JOIN and LEFT JOIN produce identical intermediate results,
-- leading to identical final aggregated results for Q1 and Q2.

-- Example data that would yield identical results for both queries:
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (101, 'Alice', 5);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (102, 'Bob', 10);
INSERT INTO EMPLOYEE (EMPLOYEE_ID, NAME, EXPERIENCE_YEARS) VALUES (103, 'Charlie', 3);

