INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (1, 102);
INSERT INTO PROJECT (PROJECT_ID, EMPLOYEE_ID) VALUES (2, 103);

-- Q1 Result:
-- PROJECT_ID | AVERAGE_YEARS
-- 1          | 7.50
-- 2          | 3.00

-- Q2 Result:
-- PROJECT_ID | AVERAGE_YEARS
-- 1          | 7.50
-- 2          | 3.00

