counterexample:
-- No counterexample can be generated under the given schema as Q1 and Q2 are equivalent.
-- The following data would result in identical empty sets for both queries:
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (101);
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (102);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 101);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (2, 102);

-- Q1 result: Empty set (because 1 != 2)
-- Q2 result: Empty set (because 1 != 2)

-- The following data would result in identical sets of all customers for both queries:
DELETE FROM PRODUCT;
DELETE FROM CUSTOMER;
INSERT INTO PRODUCT (PRODUCT_KEY) VALUES (101);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (1, 101);
INSERT INTO CUSTOMER (CUSTOMER_ID, PRODUCT_KEY) VALUES (2, 101);

-- Q1 result: {1, 2} (because 1 = 1)
-- Q2 result: {1, 2} (because 1 = 1)

