-- The two queries are logically equivalent under standard SQL and the given schema constraints.
-- No counterexample can be constructed where Q1 and Q2 produce different results.
-- Both queries correctly identify products where ALL sales occurred within '2019-01-01' and '2019-03-31'.

-- Example data where both queries return Product 1:
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (1, 'Laptop', 1200);
