INSERT INTO SALES (PRODUCT_ID, SELLER_ID, BUYER_ID, SALE_DATE, QUANTITY, PRICE) VALUES (1, 102, 202, '2019-03-10', 2, 2400);

-- Example data where both queries return nothing for Product 2 (sales outside range):
INSERT INTO PRODUCT (PRODUCT_ID, PRODUCT_NAME, UNIT_PRICE) VALUES (2, 'Mouse', 25);
